-- Projects
DROP PROCEDURE IF EXISTS sp_dynamic_xeroproject_projects;
DELIMITER $$
CREATE PROCEDURE sp_dynamic_xeroproject_projects(IN p_clientID VARCHAR(100), IN p_orgID INT)
BEGIN
    DECLARE v_OrganisationID INT DEFAULT p_orgID;
    DECLARE v_clientID VARCHAR(100) DEFAULT p_clientID;
    DECLARE v_table_name VARCHAR(255) DEFAULT CONCAT('`{client_database}`.`c', v_clientID, '_xeroproject_projects`');
    DECLARE v_stage_table VARCHAR(255) DEFAULT CONCAT('`{client_database}`.`c', v_clientID, '_', p_orgID, '_xeroproject_projectsstage`');

    SET @delete_default = CONCAT('
        DELETE FROM ', v_table_name, ' 
        WHERE OrganisationID = ', v_OrganisationID, ';
    ');

    PREPARE stmt1 FROM @delete_default;
    EXECUTE stmt1;
    DEALLOCATE PREPARE stmt1;

    SET @insert_sql = CONCAT('
        INSERT INTO ', v_table_name, '
        SELECT
            projectid,
            contactid,
            name,
            currencycode,
            minuteslogged,
            totaltaskamount,
            totalexpenseamount,
            CASE 
                WHEN CAST(minutestobeinvoiced AS CHAR) IN (''0000-00-00 00:00:00'', ''0000-00-00'', ''0001-01-01 00:00:00'', ''0001-01-01'', '''', ''null'') 
                THEN NULL 
                ELSE minutestobeinvoiced 
            END as minutestobeinvoiced,
            CASE 
                WHEN CAST(taskamounttobeinvoiced AS CHAR) IN (''0000-00-00 00:00:00'', ''0000-00-00'', ''0001-01-01 00:00:00'', ''0001-01-01'', '''', ''null'') 
                THEN NULL 
                ELSE taskamounttobeinvoiced 
            END as taskamounttobeinvoiced,
            CASE 
                WHEN CAST(taskamountinvoiced AS CHAR) IN (''0000-00-00 00:00:00'', ''0000-00-00'', ''0001-01-01 00:00:00'', ''0001-01-01'', '''', ''null'') 
                THEN NULL 
                ELSE taskamountinvoiced 
            END as taskamountinvoiced,
            CASE 
                WHEN CAST(expenseamounttobeinvoiced AS CHAR) IN (''0000-00-00 00:00:00'', ''0000-00-00'', ''0001-01-01 00:00:00'', ''0001-01-01'', '''', ''null'') 
                THEN NULL 
                ELSE expenseamounttobeinvoiced 
            END as expenseamounttobeinvoiced,
            CASE 
                WHEN CAST(expenseamountinvoiced AS CHAR) IN (''0000-00-00 00:00:00'', ''0000-00-00'', ''0001-01-01 00:00:00'', ''0001-01-01'', '''', ''null'') 
                THEN NULL 
                ELSE expenseamountinvoiced 
            END as expenseamountinvoiced,
            CASE 
                WHEN CAST(projectamountinvoiced AS CHAR) IN (''0000-00-00 00:00:00'', ''0000-00-00'', ''0001-01-01 00:00:00'', ''0001-01-01'', '''', ''null'') 
                THEN NULL 
                ELSE projectamountinvoiced 
            END as projectamountinvoiced,
            deposit,
            depositapplied,
            creditnoteamount,
            CASE 
                WHEN CAST(deadlineutc AS CHAR) IN (''0000-00-00 00:00:00'', ''0000-00-00'', ''0001-01-01 00:00:00'', ''0001-01-01'', '''', ''null'') 
                THEN NULL 
                ELSE deadlineutc 
            END as deadlineutc,
            CASE 
                WHEN CAST(totalinvoiced AS CHAR) IN (''0000-00-00 00:00:00'', ''0000-00-00'', ''0001-01-01 00:00:00'', ''0001-01-01'', '''', ''null'') 
                THEN NULL 
                ELSE totalinvoiced 
            END as totalinvoiced,
            CASE 
                WHEN CAST(totaltobeinvoiced AS CHAR) IN (''0000-00-00 00:00:00'', ''0000-00-00'', ''0001-01-01 00:00:00'', ''0001-01-01'', '''', ''null'') 
                THEN NULL 
                ELSE totaltobeinvoiced 
            END as totaltobeinvoiced,
            estimate,
            status,
            clientid,
            organisationid,
            etlinserttime,
            etlupdatetime
        FROM ', v_stage_table, ';
    ');

    PREPARE stmt2 FROM @insert_sql;
    EXECUTE stmt2;
    DEALLOCATE PREPARE stmt2;
END $$
DELIMITER ;

